window.bookSummaryJSON = "<p>Dr. Morgan Snow is a well-known sex therapist who is treating Cleo Thane, a beautiful business owner...and prostitute. Cleo caters to the wealthy and powerful and after delivering a tell-all manuscript to Dr. Snow, she disappears. A serial killer is murdering street hookers and using the book, Morgan desperately searches for clues to stop the killer before Cleo becomes his next victim.</p>"; 
